            </button>
            <div class="fkds-b3__fach-body" id="fkds-tab-abdomen" role="region">
              <div class="fkds-b3__fach-inner">
                <div class="fkds-b3__fach-content">
                  <p class="fkds-b3__p" style="font-size:0.92rem">
                    Im <strong>Abdomen</strong> und an der <strong>Schilddrüse</strong> beurteilt die FKDS die Organperfusion.
                  </p>
                  <div class="fkds-b3__table-wrap">
                    <table class="fkds-b3__table">
                      <thead>
                        <tr><th scope="col">Organ</th><th scope="col">FKDS-Anwendung</th></tr>
