.fkds-dev__wrap *::after { box-sizing: border-box; margin: 0; padding: 0; }

.fkds-dev__inner {
  max-width: 1160px; margin: 0 auto; padding: 0 2rem;
  display: flex; flex-direction: column; gap: 3rem;
}

/* Header */
.fkds-dev__header { display: flex; flex-direction: column; gap: 0.75rem; max-width: 640px; }
.fkds-dev__label {
  display: inline-flex; align-items: center; gap: 0.6rem;
